const fs = global.get("fs");
const path = global.get("path");

if (!fs || !path) {
    node.error("fs o path no están cargados.");
    return null;
}

const drivers = {};

try {

    // Leer todos los archivos de la carpeta
    const files = fs.readdirSync("/drivers");

    for (const file of files) {

        // Ignorar todo lo que no sea JSON
        if (!file.endsWith(".json")) {
            continue;
        }

        // Ruta completa
        const fullPath = path.join("/drivers", file);

        // Leer archivo
        const json = fs.readFileSync(fullPath, "utf8");

        // Convertir texto a objeto
        const driver = JSON.parse(json);

        // Nombre del driver = nombre del archivo
        const driverId = path.basename(file, ".json");

        drivers[driverId] = driver;
    }

    global.set("drivers", drivers);

    node.status({
        fill: "green",
        shape: "dot",
        text: Object.keys(drivers).length + " drivers"
    });

    msg.payload = drivers;

    return msg;

} catch(err) {

    node.status({
        fill: "red",
        shape: "ring",
        text: err.message
    });

    node.error(err);

    return null;

}

function registersToFloat(registers) {

    const buffer = Buffer.alloc(4);

    buffer.writeUInt16BE(registers[0], 0);
    buffer.writeUInt16BE(registers[1], 2);

    return buffer.readFloatBE(0);

}

let value;

switch (msg.variable.type) {

    case "float":

        value = registersToFloat(msg.payload);

        break;

    default:

        node.error("Tipo de dato no soportado: " + msg.variable.type);
        return null;
}

msg.payload = {

    point: msg.point,

    value: Number(value.toFixed(msg.variable.decimals))

};

return msg;

